<script setup lang="ts">import {onMounted,ref} from 'vue';import {useRoute} from 'vue-router';import {api} from '../api';const route=useRoute(),item=ref<any>();onMounted(async()=>{item.value=await api(`/api/admin/shipments/${route.params.id}`)})</script>
